def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, safe_bid)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 2 or no_water_days >= 1
    very_urgent = hp <= 1 or no_water_days >= 2

    base = DAILY_SALARY * (0.34 + 0.28 * scarcity)

    if supply >= 23:
        base *= 0.82
    elif supply <= 17:
        base *= 1.22

    if highest_prev >= 150:
        pressure_bid = highest_prev + 2.0
    elif highest_prev >= 110:
        pressure_bid = highest_prev + 1.5
    elif highest_prev > 0:
        pressure_bid = max(base, avg_prev + 4.0)
    else:
        pressure_bid = base

    if desperate_count >= 2:
        pressure_bid += 8.0
    elif desperate_count == 1:
        pressure_bid += 4.0

    if rich_count >= 2 and supply <= 18:
        pressure_bid += 10.0

    if urgent:
        bid = max(pressure_bid, DAILY_SALARY * 0.92)
    elif very_urgent:
        bid = max(pressure_bid, DAILY_SALARY * 1.1)
    else:
        if highest_prev >= 150 and hp >= 4 and supply >= 20:
            bid = DAILY_SALARY * 0.42
        else:
            bid = pressure_bid

    remaining_days = max(0, 10 - day)
    reserve_target = remaining_days * DAILY_SALARY * 0.45
    if not urgent and budget < reserve_target:
        bid = min(bid, DAILY_SALARY * 0.75)

    if very_urgent:
        bid = max(bid, DAILY_SALARY * 1.2)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else 0.0

    # Supply pressure: medium means we usually don't need to chase the very top bidder
    # Estimate how many water units could be contested.
    # Use explicit int() for any indexing; here we don't index.
    supply_level = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5

    # If we are in danger (low hp or many no-water days), bid aggressively to avoid death.
    if my_hp <= 2 or my_no_water_days >= 2:
        bid = DAILY_SALARY * 0.9
        return max(0.0, min(my_budget, bid))

    # If someone previously overbid heavily, we can slightly undercut rather than match.
    # Cindy showed high bids with still-low hp; likely she continues to bid for survival.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        # Undercut by a small margin; keep it moderate.
        target = min(highest_prev_bid - 2.0, DAILY_SALARY * (0.7 + 0.2 * supply_level))
        return max(0.0, min(my_budget, target))

    # Otherwise, bid around a mid level: enough to beat low bidders, not enough to waste budget.
    # Use second-highest to avoid always losing to the top bidder.
    base = DAILY_SALARY * (0.45 + 0.2 * supply_level)
    # If we have evidence of a strong competitor but not extreme, nudge above second-highest.
    if second_prev_bid > 0:
        target = max(base, second_prev_bid + 1.0)
    else:
        target = base

    # Keep within budget and avoid bidding above a reasonable cap.
    cap = DAILY_SALARY * (0.85 if my_hp <= 4 else 0.65)
    bid = min(target, cap)
    return max(0.0, min(my_budget, bid))

